// Background refreshes update this page's own server-rendered readings.
(() => {
  'use strict';
  const header=()=>document.getElementById('ukgw-live-header');
  if(!header())return;
  let due=Date.now()+Math.max(1,Number(header().dataset.refreshSeconds)||120)*1000;
  let busy=false,failures=0,uiLoading=null;
  async function ensureUI(meta){
    const expected=meta.dataset.uiVersion;
    if(typeof window.ukgwInitCharts==='function' && (!expected||window.ukgwUIVersion===expected))return;
    if(!uiLoading)uiLoading=new Promise((resolve,reject)=>{
      const script=document.createElement('script');
      script.src='/ukgw-ui.js?v='+encodeURIComponent(meta.dataset.uiAsset||expected||'recovery');
      script.async=true;
      const timer=setTimeout(()=>{script.remove();reject(Error('Chart controls unavailable'));},10000);
      script.onload=()=>{clearTimeout(timer);script.remove();if(typeof window.ukgwInitCharts==='function'&&(!expected||window.ukgwUIVersion===expected))resolve();else reject(Error('Chart version mismatch'));};
      script.onerror=()=>{clearTimeout(timer);script.remove();reject(Error('Chart script failed'));};
      document.head.appendChild(script);
    }).finally(()=>{uiLoading=null;});
    await uiLoading;
  }
  function keepChart(node){if(node.dataset.ukgwForceRefresh==='1')return false;return node.dataset.ukgwInspecting==='1'||node.contains(document.activeElement)||Boolean(node.matches?.(':hover'))||Boolean(node.querySelector('details[open]'));}
  function reconcile(old,fresh){
    if(old.nodeType!==fresh.nodeType || (old.nodeType===1 && old.tagName!==fresh.tagName)){old.replaceWith(fresh.cloneNode(true));return;}
    if(old.nodeType===3){if(old.nodeValue!==fresh.nodeValue)old.nodeValue=fresh.nodeValue;return;}
    if(old.nodeType!==1)return;
    if(old.classList.contains('ukgw-chart')){
      if(keepChart(old))return; // Never detach a chart being inspected or its focus.
      if(old.querySelector('[data-ukgw-data]')?.textContent===fresh.querySelector('[data-ukgw-data]')?.textContent){delete old.dataset.ukgwForceRefresh;return;}
      old.replaceWith(fresh.cloneNode(true));return;
    }
    for(const a of Array.from(old.attributes))if(!fresh.hasAttribute(a.name)&&!(old.tagName==='DETAILS'&&a.name==='open'))old.removeAttribute(a.name);
    for(const a of Array.from(fresh.attributes))if(!(old.tagName==='DETAILS'&&a.name==='open')&&old.getAttribute(a.name)!==a.value)old.setAttribute(a.name,a.value);
    let position=0;
    for(const child of Array.from(fresh.childNodes)){
      let existing=old.childNodes[position];
      if(child.nodeType===1&&child.id&&existing?.id!==child.id){
        const keyed=Array.from(old.children).find(el=>el.id===child.id);
        if(keyed){old.insertBefore(keyed,existing||null);existing=keyed;}
      }
      if(existing)reconcile(existing,child);else old.appendChild(child.cloneNode(true));
      position++;
    }
    while(old.childNodes.length>position)old.lastChild.remove();
  }
